CANDIDATES = [
    ("Claude Code (projeto atual)", ".claude/skills", False),
    ("Claude Code (global)", "~/.claude/skills", True),
    ("Z.ai (projeto atual)", "skills", False),
    ("Windsurf", "~/.windsurf/skills", True),
    ("Cursor", "~/.cursor/skills", True),
    ("Codex CLI", "~/.codex/skills", True),
    ("Agentes genericos (projeto)", ".agents/skills", False),
]


def extract_payload(dest_root: Path):
    target = dest_root / SKILL_NAME
    n = 0
    for rel, b64 in FILES.items():
        p = dest_root / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
        if os.name != "nt" and p.suffix == ".sh":
            p.chmod(0o755)
        if os.name != "nt" and p.name == "install.py":
            p.chmod(0o755)
        n += 1
    return target, n


def detect():
    found, seen = [], set()
    for base in [Path.cwd(), *Path.cwd().parents]:
        for label, pat, is_global in CANDIDATES:
            if is_global:
                continue
            p = base / pat
            key = str(p.resolve())
            if key not in seen and p.is_dir():
                seen.add(key)
                found.append((f"{label}  [projeto: {base.name}]", p.resolve()))
    for label, pat, is_global in CANDIDATES:
        if not is_global:
            continue
        p = Path(os.path.expanduser(pat))
        key = str(p.resolve())
        if key not in seen and p.is_dir():
            seen.add(key)
            found.append((label, p.resolve()))
    return found


def copy_skill(source: Path, dest_root: Path, name: str, assume_yes: bool):
    target = dest_root / name
    if target.exists():
        if not assume_yes:
            try:
                a = input(f"    '{target}' ja existe. Sobrescrever? [s/N] ").strip().lower()
            except EOFError:
                a = ""
            if a not in ("s", "si", "sim", "y", "yes"):
                print("    -> pulado.")
                return False
        shutil.rmtree(target)
    shutil.copytree(source, target, ignore=shutil.ignore_patterns("__pycache__", "*.pyc"))
    print(f"    [OK] instalado em: {target}")
    return True


def show_menu(found):
    print("\nPastas de skills detectadas:")
    for i, (label, path) in enumerate(found, 1):
        print(f"  {i}) {label}\n     {path}")
    print("\n  a) instalar em TODAS as acima")
    print("  c) informar outro caminho")
    print("  q) sair (a skill fica extraida na pasta atual)")
    try:
        return input("\nEscolha (numero, a, c ou q): ").strip().lower()
    except EOFError:
        return "q"


def main():
    ap = argparse.ArgumentParser(description="Instalador tudo-em-um da skill video-orchestrator")
    ap.add_argument("--list", action="store_true")
    ap.add_argument("--all", action="store_true")
    ap.add_argument("--dest", metavar="CAMINHO")
    ap.add_argument("--extract-only", action="store_true")
    ap.add_argument("--uninstall", action="store_true")
    ap.add_argument("--yes", "-y", action="store_true")
    args = ap.parse_args()
    found = detect()

    print("=" * 58)
    print(f" INSTALADOR TUDO-EM-UM · {SKILL_NAME}")
    print("=" * 58)

    if args.list:
        if not found:
            print("Nenhuma pasta de skills detectada. Use --dest CAMINHO.")
        for label, path in found:
            print(f"  {label}: {path}")
        return

    if args.uninstall:
        targets = [Path(args.dest).expanduser().resolve() / SKILL_NAME] if args.dest else [p / SKILL_NAME for _, p in found]
        for t in targets:
            if t.exists():
                shutil.rmtree(t)
                print(f"[OK] removido: {t}")
            else:
                print(f"[--] nao encontrado: {t}")
        return

    # 1) extrai o payload na pasta do proprio script
    extracted, n = extract_payload(HERE)
    print(f"[OK] {n} arquivos extraidos em: {extracted}")
    if args.extract_only:
        return

    # 2) escolhe destino e instala
    if args.dest:
        chosen = [("(informado via --dest)", Path(args.dest).expanduser().resolve())]
    elif args.all:
        chosen = found
        if not chosen:
            sys.exit("Nenhuma pasta detectada. Use --dest CAMINHO.")
    else:
        if not found:
            d = input("Nenhuma pasta detectada. Onde instalar (vazio = ./skills): ").strip()
            chosen = [("(informado manualmente)", Path(d).expanduser().resolve() if d else (HERE / "skills").resolve())]
        else:
            pick = show_menu(found)
            if pick == "q":
                print("Concluido: skill extraida na pasta atual; use-a manualmente depois.")
                return
            if pick == "c":
                d = input("Caminho completo: ").strip()
                chosen = [("(informado manualmente)", Path(d).expanduser().resolve())]
            elif pick == "a":
                chosen = found
            else:
                try:
                    chosen = [found[int(pick) - 1]]
                except (ValueError, IndexError):
                    sys.exit("Opcao invalida.")

    ok = 0
    for label, path in chosen:
        print(f"-> Instalando em {path}  ({label})")
        path.mkdir(parents=True, exist_ok=True)
        if copy_skill(extracted, path, SKILL_NAME, args.yes):
            ok += 1

    print("\n" + "=" * 58)
    print(f" CONCLUIDO · {ok} instalacao(oes).")
    print("=" * 58)
    print("""
Proximos passos:
  1. Abra o harness no projeto desejado.
  2. Peca: "Use a skill video-orchestrator (SKILL.md) para produzir os
     videos do meu produto" — o agente segue as 9 fases sozinho.
""")


if __name__ == "__main__":
    main()
